/* NIPAT desktop UI. Scientific work is performed only by the existing Python service. */
(() => {
'use strict';
const L=window.NipatI18n,t=k=>L.t(k),$=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const absent=v=>v===null||v===undefined||v===''||v==='NA'||v==='NaN';
const number=v=>absent(v)?null:Number.isFinite(Number(v))?Number(v):null;
const format=(v,d=5)=>number(v)===null?t('notAvailable'):new Intl.NumberFormat(L.language==='en'?'en-GB':'it-IT',{maximumFractionDigits:d}).format(Number(v));
const basename=p=>String(p||'').split(/[\\/]/).pop();
const moduleName=m=>({'dnp-call':t('genotypes')+' DNP','snp-call':t('genotypes')+' SNP',contamination:t('contamination'),cpi:t('cpi'),cpin:t('cpin'),analysis:t('analysis')}[m]||m||'');
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',new:'<path d="M8 3v6l-4 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-4-9V3M7 3h10M7 15h10"/>',archive:'<path d="M3 6h7l2 2h9v12H3ZM3 8V4h7l2 2h9v2"/>',activity:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',igv:'<path d="M3 5h18M3 19h18M5 9h4m2 0h6m2 0h2M3 12h6m2 0h3m2 0h3M6 15h5m2 0h8"/>',catalog:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4ZM20 4h-4a3 3 0 0 0-3 3M20 4v15h-3a4 4 0 0 0-4 2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',environment:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M9 21h6m-3-5v5M7 8l3 2-3 2m6 0h4"/>',arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m15 5-7 7 7 7"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',file:'<path d="M5 3h9l5 5v13H5ZM14 3v6h5M8 13h8m-8 4h5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4H16"/>',check:'<path d="m5 12 4 4L19 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-10v.1"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="1"/>',play:'<path d="m8 4 12 8-12 8Z"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const nav=['home','new','activity','archive','igv','catalog','settings','environment'];
const state={view:'home',boot:null,settings:{},draft:null,step:0,source:'bam',sampleKind:'bam',preview:null,error:'',jobs:[],runs:[],run:null,runId:null,runTab:'results',overview:null,files:[],module:null,entry:0,table:null,tableFile:null,tableOffset:0,tableSearch:'',allColumns:false,curves:[],archiveSearch:'',archivePage:0,archiveStatus:'all',archiveMarker:'all',catalogModule:'all',catalogType:'parameters',catalogSearch:'',catalogDefaults:false,preferences:null,baseline:null,environment:null,resourcePreview:null,igv:{reference:{fasta:'',index:''},tracks:[],locus:'',loaded:false},motion:true};
let requestId=0,draftRevision=0,igvLoadVersion=0,renderGeneration=0,toastTimer,searchTimer,pollTimer,previousFocus=null,entryLoadVersion=0,runLoadVersion=0,tableLoadVersion=0;
async function rpc(method,params={}){
 const id=++requestId,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),method==='updates.download'?7200000:method==='environment.check'?600000:method.startsWith('dialog.')?600000:180000);
 try{const response=await fetch('../api',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,method,params}),signal:controller.signal,credentials:'same-origin'});let message;try{message=await response.json()}catch{throw new Error(t('connectionError'))}if(message.error)throw new Error(typeof message.error==='string'?message.error:message.error.message||t('operationError'));if(!response.ok)throw new Error(t('connectionError'));return message.result??message;}catch(error){if(error.name==='AbortError'||error instanceof TypeError)throw new Error(t('connectionError'));throw error;}finally{clearTimeout(timer)}
}
window.nipatRpc=rpc;
function button(label,action,data={},kind='',ic=''){return `<button class="button ${kind}" data-action="${action}" ${Object.entries(data).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')}>${ic?icon(ic):''}${esc(label)}</button>`}
function heading(title,subtitle='',actions='',eyebrow=''){return `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</div>`}
function notice(message,type=''){return `<div class="notice ${type}" ${type==='error'?'role="alert"':''}>${esc(message)}</div>`}
function empty(title,copy='',action=''){return `<div class="empty-state"><div class="icon-box">${icon('info')}</div><h3>${esc(title)}</h3>${copy?`<p>${esc(copy)}</p>`:''}${action?`<div class="actions">${action}</div>`:''}</div>`}
function select(label,id,options,value,attrs=''){return `<div class="field"><label for="${id}">${esc(label)}</label><select id="${id}" class="input" ${attrs}>${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`}
function input(label,id,value,attrs='',help=''){return `<div class="field"><label for="${id}">${esc(label)}</label><input id="${id}" class="input" value="${esc(value??'')}" ${attrs}>${help?`<p class="help">${esc(help)}</p>`:''}</div>`}
function fileField(label,key,value,filter='all'){return `<div class="field"><label>${esc(label)}</label><div class="file-field"><input class="input" value="${esc(value||'')}" readonly placeholder="${esc(t('chooseFile'))}" aria-label="${esc(label)}">${button(t('browse'),'choose-path',{key,filter},'small','archive')}${value?button(t('remove'),'clear-path',{key},'quiet small','close'):''}</div></div>`}
function badge(status){return `<span class="badge ${['failed','error'].includes(status)?'error':['running','queued','cancelling','starting','cancel_requested'].includes(status)?'warning':'neutral'}">${esc(t(status)||status)}</span>`}
function date(value){if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?esc(value):esc(d.toLocaleString(L.language==='en'?'en-GB':'it-IT',{dateStyle:'short',timeStyle:'short'}))}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),5000)}
function defaults(){return Object.fromEntries(Object.entries(state.settings).map(([m,w])=>[m,Object.fromEntries(Object.entries(w.parameters||{}).map(([k,p])=>[k,p.default]))]))}
function blankDraft(){const scientific=defaults();for(const [m,values]of Object.entries(state.preferences?.scientific_settings||{}))Object.assign(scientific[m]||{},values);return {name:'',caller:'dnp',samples:[],branches:{DNP:[],SNP:[]},reference:null,resources:{DNP:{},SNP:{}},families:{cpi:[],cpin:[]},scientific_settings:scientific,execution:{input_hashes:'auto',execution_mode:'auto',cpus:null,memory_mb:null,pids_limit:null,max_workers:null,dnp_block_mib:32,dnp_block_loci:64,performance_diagnostics:false,...(state.boot?.execution||{}),...(state.preferences?.execution||{})}}}

function archiveRows(){const runs=filteredRuns(),limit=25,pages=Math.max(1,Math.ceil(runs.length/limit));state.archivePage=Math.min(state.archivePage,pages-1);const offset=state.archivePage*limit;return runRows(runs.slice(offset,offset+limit))+`<div class="pager"><span>${format(offset+1,0)}–${format(Math.min(offset+limit,runs.length),0)} / ${format(runs.length,0)}</span><div class="actions"><button class="button small" data-action="archive-page" data-page="${state.archivePage-1}" ${state.archivePage===0?'disabled':''}>${t('previous')}</button><button class="button small" data-action="archive-page" data-page="${state.archivePage+1}" ${state.archivePage+1>=pages?'disabled':''}>${t('next')}</button></div></div>`}
function normalizeDraft(value){const base=blankDraft(),draft=clone(value.draft||value);return {...base,...draft,branches:{...base.branches,...draft.branches},resources:{DNP:{...base.resources.DNP,...draft.resources?.DNP},SNP:{...base.resources.SNP,...draft.resources?.SNP}},families:{...base.families,...draft.families},scientific_settings:Object.fromEntries(Object.entries(base.scientific_settings).map(([module,values])=>[module,{...values,...draft.scientific_settings?.[module]}])),execution:{...base.execution,...draft.execution}}}
function applyDraft(value){state.draft=normalizeDraft(value);state.source=state.draft.caller==='tables'?'tables':state.draft.samples.some(sample=>sample.kind.endsWith('-table'))?'mixed':'bam';state.sampleKind=state.source==='tables'?'dnp-table':'bam';state.step=0;invalidate()}
function submittedDraft(){const draft=clone(state.draft),markers=activeMarkers();for(const marker of ['DNP','SNP'])if(!markers.includes(marker))draft.branches[marker]=[];const selected=markers.flatMap(marker=>draft.branches[marker]||[]);if(!draft.samples.some(sample=>sample.kind==='bam'))draft.reference=null;for(const module of ['cpi','cpin'])if(!selected.includes(module))draft.families[module]=[];for(const marker of ['DNP','SNP']){const branch=draft.branches[marker],resources=draft.resources[marker];if(!callerRuns(marker)&&!branch.includes('contamination'))delete resources.panel;if(!branch.some(module=>module==='cpi'||module==='cpin'))delete resources.popfreq;if(!branch.includes('contamination'))delete resources.contamination_panel;if(!branch.includes('cpi'))delete resources.cpi_cutoffs;if(!branch.includes('cpin'))delete resources.cpin_panel;}return draft}
function activeMarkers(){const set=new Set(state.draft.caller==='both'?['DNP','SNP']:state.draft.caller==='tables'?[]:[state.draft.caller.toUpperCase()]);for(const s of state.draft.samples)if(s.kind==='dnp-table')set.add('DNP');else if(s.kind==='snp-table')set.add('SNP');return [...set]}
function callerRuns(marker){return state.draft.caller==='both'||state.draft.caller===marker.toLowerCase()}
function selectedModules(){return [...new Set([...(state.draft.caller==='tables'?[]:state.draft.caller==='both'?['dnp-call','snp-call']:[state.draft.caller+'-call']),...activeMarkers().flatMap(m=>state.draft.branches[m]||[])])]}
function invalidate(){++draftRevision;state.preview=null;state.error=''}
function setPath(key,value){const [root,a,b]=key.split('.');if(root==='reference')state.draft.reference=value;else if(root==='resource')state.draft.resources[a][b]=value;else if(root==='preference')state.preferences[a]=value;else if(root==='igv-reference')state.igv.reference[a]=value;else if(root==='igv-track')state.igv.tracks[Number(a)][b]=value;else if(root==='cutoff')state.draft.resources[a].cpi_cutoffs[Number(b)].path=value;invalidate()}
async function choosePath(key,filter='all',multiple=false){const extensions={bam:['bam'],pileup:['txt','tsv','pileup'],table:['txt','tsv','csv'],reference:['fa','fasta','fna'],index:['fai','bai','crai','csi','tbi'],alignment:['bam','cram','vcf','bed','gff','gff3','gtf','bw','bigwig','bb','bigbed','wig','bedgraph','seg','gz','bgz'],all:['*']}[filter]||['*'];const result=await rpc('dialog.open',{kind:filter==='directory'?'directory':'files',directory:filter==='directory',multiple,title:t('browse'),filters:[{name:t('selectedFile'),extensions}]});const paths=Array.isArray(result)?result:result?.paths||[];if(!paths.length)return[];if(key)setPath(key,paths[0]);return paths}
async function loadRuns(){const runs=[];let offset=0;while(true){const result=await rpc('runs.list',{offset,limit:1000});const page=result.runs||result||[];runs.push(...page);if(!result.has_more||!page.length)break;offset+=page.length;}state.runs=[...new Map(runs.map(run=>[run.id,run])).values()];return state.runs}
function filteredRuns(){const q=state.archiveSearch.toLowerCase();return state.runs.filter(r=>(state.archiveStatus==='all'||r.status===state.archiveStatus)&&(state.archiveMarker==='all'||r.markers?.includes(state.archiveMarker))&&[r.name,r.id,r.started_at,...(r.samples||[]).map(s=>s.label||s.id)].join(' ').toLowerCase().includes(q))}
function runRows(runs){if(!runs.length)return empty(t('noRuns'),t('noRunsCopy'),button(t('new'),'navigate',{view:'new'},'primary','plus')+button(t('openFolder'),'import-run',{},'','archive'));return `<div class="table-scroll" tabindex="0"><table class="table"><thead><tr><th>${t('name')}</th><th>${t('date')}</th><th>${t('analysis')}</th><th>${t('status')}</th><th><span class="screen-reader-only">${t('open')}</span></th></tr></thead><tbody>${runs.map(r=>`<tr><td><b>${esc(r.name||r.id)}</b><small>${r.samples?.length||0} ${t('samples').toLowerCase()} · ${esc((r.markers||[]).join(' / '))}</small></td><td>${date(r.started_at)}</td><td>${esc((r.modules||[r.workflow]).map(m=>moduleName(typeof m==='string'?m:m.module)).join(' · '))}</td><td>${badge(r.status)}</td><td>${button(t('openResults'),'open-run',{id:r.id},'primary small','arrow')}</td></tr>`).join('')}</tbody></table></div>`}
function renderHome(){return heading(t('welcome'),t('welcomeCopy'),button(t('new'),'navigate',{view:'new'},'primary','plus'))+`<div class="grid two-columns"><button class="home-card" data-action="navigate" data-view="new"><span class="icon-box">${icon('new')}</span><span><h2>${t('new')}</h2><p>${t('newCopy')}</p></span>${icon('arrow')}</button><button class="home-card" data-action="navigate" data-view="archive"><span class="icon-box">${icon('archive')}</span><span><h2>${t('archive')}</h2><p>${t('archiveCopy')}</p></span>${icon('arrow')}</button></div><section class="panel section-gap"><div class="panel-header"><h2>${t('recent')}</h2>${button(t('allExperiments'),'navigate',{view:'archive'},'','arrow')}</div>${runRows(state.runs.slice(0,5))}</section><div class="grid two-columns section-gap"><section class="panel"><div class="panel-body"><h2>${t('igv')}</h2><p class="help section-gap">${t('igvHelp')}</p><div class="actions section-gap">${button(t('open'),'navigate',{view:'igv'},'','igv')}</div></div></section><section class="panel"><div class="panel-body"><h2>${t('catalog')}</h2><p class="help section-gap">${Object.values(state.settings).reduce((n,w)=>n+Object.keys(w.parameters||{}).length,0)} ${t('parameters').toLowerCase()} · ${Object.values(state.settings).reduce((n,w)=>n+Object.keys(w.constants||{}).length,0)} ${t('constants').toLowerCase()}</p><div class="actions section-gap">${button(t('open'),'navigate',{view:'catalog'},'','catalog')}</div></div></section></div>`}
function renderInputs(){const d=state.draft,markers=activeMarkers();return `<div class="section-title"><h2>${t('addSamples')}</h2></div><div class="form-row">${input(t('experimentName'),'experiment-name',d.name,'data-draft="name" maxlength="120" placeholder="'+esc(t('experimentPlaceholder'))+'"')}${select(t('startFrom'),'source',[['bam',t('rawInputs')],['tables',t('existingTables')],['mixed',t('mixedInputs')]],state.source,'data-field="source"')}</div>${state.source!=='tables'?`<fieldset class="choice-fieldset"><legend>${t('whichMarkers')}</legend><div class="choices">${[['dnp','onlyDnp','dnpDescription'],['snp','onlySnp','snpDescription'],['both','both','bothDescription']].map(([v,key,help])=>`<label class="choice ${d.caller===v?'selected':''}"><input type="radio" name="caller" value="${v}" data-draft="caller" ${d.caller===v?'checked':''}><span><b>${t(key)}</b><small>${t(help)}</small></span></label>`).join('')}</div></fieldset>`:''}<div class="toolbar">${select(t('sampleKind'),'sample-kind',(state.source==='tables'?[['dnp-table',t('dnpTable')],['snp-table',t('snpTable')]]:state.source==='bam'?[['bam',t('bam')],['snp-pileup',t('snpPileup')]]:[['bam',t('bam')],['snp-pileup',t('snpPileup')],['dnp-table',t('dnpTable')],['snp-table',t('snpTable')]]),state.sampleKind,'data-field="sampleKind"')}${button(t('addSamples'),'add-samples',{},'primary','plus')}</div><div class="table-scroll"><table class="table"><thead><tr><th>${t('sampleName')}</th><th>${t('sampleFile')}</th><th>${t('fileType')}</th><th></th></tr></thead><tbody>${d.samples.map((s,i)=>`<tr><td class="sample-name"><input class="input" value="${esc(s.id)}" data-sample="${i}" maxlength="48" aria-label="${t('sampleName')} ${i+1}"></td><td><b>${esc(basename(s.path))}</b><details class="file-name"><summary>${t('details')}</summary>${esc(s.path)}</details></td><td>${esc({bam:t('bam'),'snp-pileup':t('snpPileup'),'dnp-table':t('dnpTable'),'snp-table':t('snpTable')}[s.kind])}</td><td>${button(t('remove'),'remove-sample',{index:i},'quiet small','close')}</td></tr>`).join('')}</tbody></table>${!d.samples.length?empty(t('noSamples')):''}</div><p class="help section-gap">${t('sampleIdHelp')}</p>${d.samples.some(s=>s.kind==='bam')?`<div class="form-row">${fileField(t('reference'),'reference',d.reference,'reference')}<p class="help">${t('referenceHelp')}</p></div>`:''}${d.caller!=='tables'?`<div class="form-row">${(d.caller==='both'?['DNP','SNP']:[d.caller.toUpperCase()]).map(m=>fileField(t('panel')+' '+m,'resource.'+m+'.panel',d.resources[m].panel,'table')).join('')}</div>`:''}`}
function renderFamilies(module){const rows=state.draft.families[module],roles=module==='cpi'?['mother','father']:['mother','father','child'];const samples=[...new Set(state.draft.samples.map(s=>s.id))];return `<section class="section-gap"><div class="section-title"><h3>${moduleName(module)} · ${t('family')}</h3>${button(t('addFamily'),'add-family',{module},'small','plus')}</div><p class="help">${t('familyHelp')}</p>${rows.map((r,i)=>`<div class="family-row ${module==='cpi'?'pair':''}">${input(t('familyName'),`${module}-family-${i}`,r.id,`data-family="${module}|${i}|id" maxlength="48"`)}${roles.map(role=>select(t(role==='mother'&&module==='cpi'?'maternalCfdna':role),`${module}-${i}-${role}`,[['',t('assign')],...samples.map(s=>[s,s])],r[role]||'',`data-family="${module}|${i}|${role}"`)).join('')}${button(t('remove'),'remove-family',{module,index:i},'quiet small','close')}</div>`).join('')}</section>`}
function renderAnalyses(){const d=state.draft,markers=activeMarkers(),selected=selectedModules();return `<h2>${t('whichAnalyses')}</h2><p class="muted section-gap">${t(d.caller==='tables'?'tableAnalyses':'optionalAnalyses')}</p><div class="grid ${markers.length>1?'two-columns':''} section-gap">${markers.map(m=>`<section class="branch"><div class="branch-header"><b>${m}</b><span class="badge neutral">${t(callerRuns(m)?'genotypes':'existingTables')}</span></div><div class="branch-body">${['contamination','cpi','cpin'].map(mod=>`<label class="check-row"><input type="checkbox" data-branch="${m}|${mod}" ${d.branches[m].includes(mod)?'checked':''}><span><b>${moduleName(mod)}</b><p>${t(mod+'Help')}</p></span></label>`).join('')}</div></section>`).join('')}</div>${selected.includes('cpi')?renderFamilies('cpi'):''}${selected.includes('cpin')?renderFamilies('cpin'):''}<div class="form-row">${markers.filter(m=>d.branches[m].some(a=>a==='cpi'||a==='cpin')).map(m=>fileField(t('population')+' '+m,'resource.'+m+'.popfreq',d.resources[m].popfreq,'table')).join('')}</div><details class="disclosure"><summary>${t('optionalPanels')}</summary><div class="details-body">${markers.map(m=>`<h3 class="section-gap">${m}</h3><div class="form-row">${d.branches[m].includes('contamination')?fileField(t('contaminationPanel'),'resource.'+m+'.contamination_panel',d.resources[m].contamination_panel,'table'):''}${d.branches[m].includes('cpin')?fileField(t('cpinPanel'),'resource.'+m+'.cpin_panel',d.resources[m].cpin_panel,'table'):''}</div>${d.branches[m].includes('cpi')?`<div class="section-title"><h3>${t('cpiPanels')}</h3>${button(t('addPanel'),'add-cutoff',{marker:m},'small','plus')}</div><p class="help">${t('allSitesHelp')}</p>${(d.resources[m].cpi_cutoffs||[]).map((c,i)=>`<div class="form-row">${input(t('name'),`cutoff-${m}-${i}`,c.label,`data-cutoff="${m}|${i}"`)}<div class="actions">${fileField(t('panel'),`cutoff.${m}.${i}`,c.path,'table')}${button(t('remove'),'remove-cutoff',{marker:m,index:i},'quiet small','close')}</div></div>`).join('')}`:''}`).join('')}</div></details>`}
function phase(key){if(['min_base_quality','min_mapping_quality','max_depth','mapping_quality_adjustment','baq','redo_baq','count_overlaps','include_orphans','excluded_flags'].includes(key))return 'phasePileup';if(['err_const_snp','err_const_dnp','min_fetal_reads','min_child_reads','include_zero'].includes(key))return 'phaseEstimate';if(key.startsWith('log_cpi_'))return 'phasePlot';return 'phaseSelection'}
function parameterVisible(m,key,all=false){if(all)return true;if(phase(key)==='phasePileup'&&!state.draft.samples.some(s=>s.kind==='bam'))return false;if(key==='err_const_snp'&&!activeMarkers().includes('SNP'))return false;if(key==='err_const_dnp'&&!activeMarkers().includes('DNP'))return false;return true}
function range(def){let txt='';if(def.minimum!==undefined||def.maximum!==undefined)txt=(def.exclusive_minimum?'(':'[')+(def.minimum??'−∞')+'; '+(def.maximum??'+∞')+']';if(def.choices)txt=def.choices.map(choiceLabel).join(' / ');if(def.unit)txt+=(txt?' · ':'')+(L.language==='en'?({proporzione:'proportion',probabilita:'probability',letture:'reads',coefficiente:'coefficient','bitmask SAM':'SAM flags'}[def.unit]||def.unit):def.unit);return txt}
function choiceLabel(v){return {all:t('allCompatible'),heterozygous:t('heterozygous'),both:t('both'),all_compatible_sites:t('allCompatible'),heterozygous_child_sites:t('heterozygous')}[v]||v}
function displayValue(v){if(typeof v==='boolean')return t(v?'yes':'no');if(Array.isArray(v))return v.join(', ');if(typeof v==='object')return JSON.stringify(v);return String(v??'')}
function parameterRows(module,scope='draft',readonly=false,all=false){const w=state.settings[module],values=scope==='defaults'?(state.preferences.scientific_settings?.[module]||{}):state.draft.scientific_settings[module];const entries=Object.entries(w.parameters||{}).filter(([key,def])=>parameterVisible(module,key,all)&&[L.field(key),L.description(key,def),t(phase(key))].join(' ').toLowerCase().includes(state.catalogSearch.toLowerCase()));const groups=[...new Set(entries.map(([k])=>phase(k)))];return groups.map(group=>`<section class="parameter-group"><h3>${t(group)}</h3>${entries.filter(([k])=>phase(k)===group).map(([key,def])=>{const value=values?.[key]??def.default;const attrs=`data-parameter="${module}|${key}|${scope}"`;return `<div class="parameter-row"><div><h3>${esc(L.field(key))}</h3><p>${esc(L.description(key,def))}</p><div class="range">${t('allowed')}: ${esc(range(def)||'—')} · ${t('defaultValue')}: ${esc(key==='excluded_flags'?archivedFlagNames(def.default):def.choices?choiceLabel(def.default):displayValue(def.default))}</div></div><div class="parameter-value">${readonly?`<b>${esc(key==='excluded_flags'?archivedFlagNames(value):def.choices?choiceLabel(value):displayValue(value))}</b>`:def.type==='boolean'?`<label class="check-row"><input type="checkbox" ${attrs} ${value?'checked':''}><span>${t('enabled')}</span></label>`:def.choices?`<select class="input" ${attrs} aria-label="${esc(L.field(key))}">${def.choices.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(choiceLabel(v))}</option>`).join('')}</select>`:`<input class="input" type="number" ${attrs} value="${esc(value)}" ${def.minimum!==undefined?`min="${def.minimum}"`:''} ${def.maximum!==undefined?`max="${def.maximum}"`:''} step="${def.type==='integer'?'1':'any'}" aria-label="${esc(L.field(key))}">`}${!readonly?button(t('reset'),'reset-param',{module,key,scope},'quiet small'):''}</div></div>${key==='excluded_flags'&&!readonly?flagsEditor(module,value,scope):''}`}).join('')}</section>`).join('')}
function flagsEditor(module,value,scope){const flags=[[4,'Non allineate','Unmapped'],[8,'Compagno non allineato','Unmapped mate'],[256,'Allineamenti secondari','Secondary alignments'],[512,'Controllo qualità non superato','Failed quality control'],[1024,'Duplicati','Duplicates'],[2048,'Allineamenti supplementari','Supplementary alignments']];return `<details class="disclosure"><summary>${L.field('excluded_flags')}</summary><div class="details-body flags">${flags.map(([bit,it,en])=>`<label><input type="checkbox" data-flag="${module}|${bit}|${scope}" ${(Number(value)&bit)?'checked':''}>${esc(L.language==='en'?en:it)}</label>`).join('')}</div></details>`}
function executionFields(execution,scope='draft'){return `<p class="help">${t('executionHelp')}</p><div class="execution-grid section-gap">${select(t('mode'),scope+'-execution-mode',[['auto',t('automatic')],['serial',t('serial')]],execution.execution_mode||'auto',`data-execution="execution_mode|${scope}"`)}${[['max_workers','maxWorkers',1,1024],['cpus','cpuLimit',.1,1024],['memory_mb','memoryLimit',128,1048576],['pids_limit','processLimit',16,1048576],['dnp_block_mib','blockSize',1,4096],['dnp_block_loci','blockLoci',1,1000000]].map(([k,label,min,max])=>input(t(label),scope+'-'+k,execution[k]??'',`type="number" min="${min}" max="${max}" step="${k==='cpus'?'any':'1'}" data-execution="${k}|${scope}" placeholder="${t('automatic')}"`)).join('')}${select(t('hashes'),scope+'-input-hashes',[['auto',t('automatic')],['full',t('fullHashes')]],execution.input_hashes||'auto',`data-execution="input_hashes|${scope}"`)}</div><label class="check-row section-gap"><input type="checkbox" data-execution="performance_diagnostics|${scope}" ${execution.performance_diagnostics?'checked':''}><span>${t('diagnostics')}</span></label>`}
function renderParameters(){return `<h2>${t('parameters')}</h2>${selectedModules().map(m=>`<details class="disclosure" open><summary>${moduleName(m)}</summary><div class="details-body">${parameterRows(m)}</div></details>`).join('')}<details class="disclosure"><summary>${t('execution')}</summary><div class="details-body">${executionFields(state.draft.execution)}</div></details>`}
function renderReview(){const d=state.draft,processed=state.preview?.samples,labels=processed?[...new Set(processed.map(sample=>sample.biological_id||sample.id||sample.sample_id))]:d.samples.map(sample=>sample.id),branches=state.preview?.analyses_by_marker||d.branches;return `<h2>${t('review')}</h2><div class="review-block"><dl class="review-list"><dt>${t('experimentName')}</dt><dd>${esc(d.name)}</dd><dt>${t('samples')}</dt><dd>${labels.map(esc).join(', ')||t('emptyValue')}</dd><dt>${t('markers')}</dt><dd>${activeMarkers().join(' / ')}</dd></dl></div><div class="review-block"><h3>${t('expectedResults')}</h3>${activeMarkers().map(marker=>{const analyses=[...(callerRuns(marker)?[t('genotypes')]:[]),...(branches[marker]||[]).map(moduleName)];return `<p><b>${marker}</b> · ${analyses.length?analyses.join(' · '):(L.language==='it'?'Nessuna analisi selezionata: queste tabelle non saranno elaborate.':'No analysis selected: these tables will not be processed.')}</p>`}).join('')}</div><div class="review-block"><h3>${t('resultLocation')}</h3><p>${t('archive')} → ${esc(d.name)} → ${t('results')}</p></div>${state.preview?`<div class="section-gap">${notice(t('validated'))}<ol class="plan-list">${state.preview.steps.map(step=>`<li>${esc(moduleName(step.workflow||step.module))}${step.parameters?.marker_type?' · '+esc(step.parameters.marker_type):''}${step.inputs?.sample?' · '+esc(step.inputs.sample):''}</li>`).join('')}</ol></div>`:`<p class="help section-gap">${t('validationRequired')}</p>`}<div class="actions section-gap">${button(t('validate'),'validate-plan',{},'','check')}</div>`}
function renderNew(){const d=state.draft;return heading(t('new'),t('newCopy'))+`${state.error?notice(state.error,'error'):''}<div class="form-layout section-gap"><section class="panel"><div class="steps" role="tablist">${['samples','analysis','parameters','review'].map((key,i)=>`<button class="step ${state.step===i?'active':''}" data-action="step" data-index="${i}" role="tab" aria-selected="${state.step===i}"><span>${i+1}</span>${t(key)}</button>`).join('')}</div><div class="panel-body">${[renderInputs,renderAnalyses,renderParameters,renderReview][state.step]()}</div><div class="form-footer"><span class="help">${state.step+1} / 4</span><div class="actions">${state.step?button(t('back'),'step',{index:state.step-1},'','back'):''}${state.step<3?button(t('continue'),'step',{index:state.step+1},'primary','arrow'):`<button class="button primary" data-action="start-analysis" ${state.preview?'':'disabled'}>${icon('play')}${t('startAnalysis')}</button>`}</div></div></section><aside class="side-summary"><h3>${t('review')}</h3><dl><div><dt>${t('name')}</dt><dd>${esc(d.name)||'—'}</dd></div><div><dt>${t('samples')}</dt><dd>${d.samples.length}</dd></div><div><dt>${t('markers')}</dt><dd>${activeMarkers().join(' / ')||'—'}</dd></div><div><dt>${t('expectedResults')}</dt><dd>${selectedModules().map(moduleName).map(esc).join(', ')||'—'}</dd></div></dl></aside></div>`}
function renderArchive(){if(state.run)return renderRun();return heading(t('archive'),t('archiveCopy'),button(t('openFolder'),'import-run',{},'','archive')+button(t('new'),'navigate',{view:'new'},'primary','plus'))+`<section class="panel"><div class="panel-body"><div class="toolbar"><input class="input stretch" id="archive-search" placeholder="${t('archiveSearch')}" aria-label="${t('search')}" value="${esc(state.archiveSearch)}" data-search="archive">${select(t('status'),'archive-status',[['all',t('all')],['succeeded',t('succeeded')],['failed',t('failed')],['running',t('running')],['interrupted',t('interrupted')]],state.archiveStatus,'data-field="archiveStatus"')}${select(t('markers'),'archive-marker',[['all',t('all')],['DNP','DNP'],['SNP','SNP']],state.archiveMarker,'data-field="archiveMarker"')}</div></div>${filteredRuns().length?archiveRows():empty(t(state.runs.length?'noFilteredRuns':'noRuns'),state.runs.length?'':t('noRunsCopy'))}</section>`}
function jobProgress(job){const p=job.progress;if(p&&Number.isFinite(p.completed)&&Number.isFinite(p.total)&&p.total>0)return Math.max(0,Math.min(100,p.completed/p.total*100));if(typeof p==='number')return Math.max(0,Math.min(100,p));if(p&&typeof p==='object'){const value=p.percent??p.percentage??p.overall_percent;if(Number.isFinite(Number(value)))return Math.max(0,Math.min(100,Number(value)))}return null}
function terminal(job){return ['succeeded','completed','failed','cancelled','canceled','interrupted','planned'].includes(job.status)}
function progressLabel(p){if(!p)return '';const phases={'preparation':['Preparazione degli input','Preparing inputs'],'plan-preflight':['Verifica del piano','Checking plan'],'presentation-preparation':['Preparazione dei risultati','Preparing results'],'r-execution':['Calcolo R','R computation'],'output-validation':['Controllo dei risultati','Checking outputs'],'presentation-finalization':['Esportazione dei risultati','Exporting results'],'plan-presentation':['Riepilogo delle analisi','Analysis summary'],'pileup':['Preparazione del pileup','Preparing pileup'],'pileup-index':['Indicizzazione del pileup','Indexing pileup'],'pileup-reading':['Lettura del pileup','Reading pileup'],'dnp-processing':['Calcolo DNP','DNP computation'],'plots':['Creazione dei grafici','Creating plots'],'dnp-indexed-selection':['Selezione delle letture','Selecting reads'],'dnp-indexed-pileup':['Pileup dalle regioni indicizzate','Pileup from indexed regions'],'dnp-pileup':['Preparazione pileup DNP','Preparing DNP pileup']};const phase=phases[p.phase]?.[L.language==='en'?1:0]||p.phase||t('progressUnknown');return [p.workflow?moduleName(p.workflow):'',phase,...(p.sample_ids||[])].filter(Boolean).join(' · ')}
function renderActivity(){return heading(t('activity'),t('jobHelp'),button(t('reload'),'refresh-jobs',{},'','activity'))+(state.jobs.length?state.jobs.map(job=>{const p=jobProgress(job);return `<section class="panel section-gap"><div class="progress-card"><div class="job-header"><div><h2>${esc(job.name||job.run_name||job.id)}</h2><p>${esc(progressLabel(job.progress)||job.message||'')}</p></div>${badge(job.status)}</div>${!terminal(job)?`<div class="job-progress section-gap"><div class="dna-loader ${state.motion?'':'paused'}" aria-hidden="true"></div><span>${p===null?t('progressUnknown'):format(p,1)+' % · '+(L.language==='it'?'fase corrente':'current phase')}</span></div>`:''}<div class="progress-track ${p===null&&!terminal(job)?'indeterminate':''}"><span style="width:${p??(job.status==='succeeded'?100:0)}%"></span></div>${job.error?notice(typeof job.error==='string'?job.error:job.error.message,'error'):''}<div class="actions section-gap">${!terminal(job)?button(t('stopAnalysis'),'cancel-job',{id:job.id},'danger','stop'):''}${job.run_id?button(t('openResults'),'open-run',{id:job.run_id},'primary','arrow'):''}</div><details class="disclosure"><summary>${t('logs')}</summary><div class="details-body"><pre class="job-log">${esc(Array.isArray(job.logs)?job.logs.map(x=>typeof x==='string'?x:JSON.stringify(x)).join('\n'):job.logs||'')}</pre></div></details></div></section>`}).join(''):`<section class="panel">${empty(t('noJobs'),'',button(t('new'),'navigate',{view:'new'},'primary','plus'))}</section>`)}
function currentGroup(){return (state.overview?.modules||[]).find(g=>g.module+'|'+g.marker===state.module)}
function currentEntry(){return currentGroup()?.entries?.[state.entry]}
function entryLabel(entry){return (entry.label||entry.sample_label||entry.family_id||t('summary'))+(entry.analysis?' · '+choiceLabel(entry.analysis):'')+(entry.cutoff?' · '+entry.cutoff:'')}
function metricValue(metric){if(metric.available===false||absent(metric.value))return t('notAvailable');const n=number(metric.value);if(n===null)return esc(metric.value);const v=n*(metric.scale??1);const value=v!==0&&(Math.abs(v)<.00001||Math.abs(v)>=1e7)?v.toExponential(5).replace('.',L.language==='it'?',':'.'):format(v,6);return value+(metric.unit==='%'?' %':['percentage_points','punti %','percentage points'].includes(metric.unit)?(L.language==='it'?' punti %':' percentage points'):'')}
function resultCell(value,column){if(absent(value))return `<span class="muted">${t('notAvailable')}</span>`;const key=column.key;if(/^(chr|chrom|chromosome|pos|pos1|pos2|start|end|id|sample_id|family_id)$/i.test(key))return esc(value);if(column.values&&column.values[value])return esc(column.values[value]);if(value==='TRUE'||value==='FALSE')return t(value==='TRUE'?'yes':'no');if(key==='Analysis')return esc(choiceLabel(value));if(key==='Status'){const names={eligible:['Ammissibile','Eligible'],mother_child_incompatible:['Incompatibilità madre–figlio','Mother–child incompatibility'],mother_not_homozygous:['Madre non omozigote','Mother not homozygous'],insufficient_child_support:['Letture del figlio insufficienti','Insufficient child reads'],quality_filter:['Filtro di qualità non superato','Quality filter not passed'],father_unassigned:['Genotipo paterno non assegnato','Father genotype unassigned']};return esc(names[value]?.[L.language==='en'?1:0]||value)}if(number(value)!==null){const n=Number(value)*(column.scale??1);const display=n!==0&&(Math.abs(n)<.00001||Math.abs(n)>=1e7)?n.toExponential(5).replace('.',L.language==='it'?',':'.'):format(n,6);return `<span title="${esc(t('originalValue')+': '+value)}">${esc(display)}${column.unit==='%'?' %':['percentage_points','punti %','percentage points'].includes(column.unit)?(L.language==='it'?' punti %':' percentage points'):''}</span>`}return esc(value)}
function metrics(entries){return `<div class="metrics">${entries.map(m=>{const v=metricValue(m);return `<div class="metric"><span>${esc(m.label)}</span><strong class="${v.length>18?'long':''}" title="${esc(absent(m.raw_value)?m.value??'':m.raw_value)}">${v}</strong>${m.description?`<small>${esc(m.description)}</small>`:''}</div>`}).join('')}</div>`}
function genotypeBars(entry){const counts=entry.genotype_counts;if(!counts)return '';const max=Math.max(1,...Object.values(counts));return `<section class="section-gap"><h3>${t('genotypeDistribution')}</h3><div class="genotype-bars">${['0/0','0/1','1/1','unassigned'].map(key=>`<div><span>${key==='unassigned'?t('unassigned'):key}</span><div class="bar-track"><span style="width:${(counts[key]||0)/max*100}%"></span></div><b>${format(counts[key]||0,0)}</b></div>`).join('')}</div></section>`}
function resultHelp(){return `<details class="disclosure"><summary>${t('resultHelpTitle')}</summary><div class="details-body"><p>${t('resultHelp')}</p></div></details>`}
function renderResultsSummary(){
 const groups=state.overview?.modules||[];
 return `<div class="section-title"><h2>${t('results')}</h2>${button(t('downloadAll'),'export-run',{},'','download')}</div><div class="module-grid">${['dnp-call','snp-call','contamination','cpi','cpin'].map(module=>{
  const found=groups.filter(g=>g.module===module),available=found.some(g=>g.entries?.length||(g.files||[]).some(f=>['table','pdf'].includes(f.kind)));
  const statuses=found.map(g=>{const label=g.status==='pending'?(L.language==='it'?'In attesa':'Pending'):t(g.status||'planned');return esc(g.marker)+' · '+esc(label)}).join('<br>');
  return `<article class="module-card"><div><h3>${moduleName(module)}</h3><p>${found.length?statuses:t('notRun')}</p></div><div><span class="help">${found.length?t(available?'available':'noResults'):t('notRun')}</span>${found.length?button(t(available?'openResults':'details'),'result-module',{module:found[0].module+'|'+found[0].marker},'primary small','arrow'):button(t('prepareAnalysis'),'prepare-module',{module},'small','plus')}</div></article>`
 }).join('')}</div>${resultHelp()}`
}
function shownColumns(table,all=false){if(all)return table.columns;const preferred=['chr','pos','pos1','pos2','REF','ALT','GT','N_REF','N_ALT','N_Other','contamination','Status','Paternity_Index','Mismatch','Child_support','GT_child','CPI','Log10_CPI','log_CPI','Iteration','Min_child_reads','Through_min_child_reads','N_sites','Matching_sites','Mismatching_sites'];const selected=table.columns.filter(c=>preferred.includes(c.key));return selected.length?selected:table.columns.slice(0,8)}
function tableView(table,{compact=false,all=state.allColumns}={}){if(!table)return empty(t('noResults'));const columns=shownColumns(table,all);return `<div class="table-scroll" tabindex="0" role="region" aria-label="${esc(table.file?.label||t('results'))}"><table class="table result-table"><caption>${format(table.matched,0)} / ${format(table.total,0)} ${t('rows')}</caption><thead><tr>${columns.map(c=>`<th scope="col" title="${esc(c.description||'')}">${esc(c.label)}${c.unit&&!['proportion','log10','%','percentage_points'].includes(c.unit)?`<small> ${esc(c.unit)}</small>`:''}</th>`).join('')}<th scope="col">${t('details')}</th></tr></thead><tbody>${table.rows.map((row,i)=>`<tr>${columns.map(col=>`<td>${resultCell(row[col.key],col)}</td>`).join('')}<td>${button(t('details'),'row-details',{file:table.file.id,row:table.row_numbers?.[i]??table.offset+i},'quiet small','arrow')}</td></tr>`).join('')}</tbody></table>${!table.rows.length?empty(t('noRows')):''}</div>${compact?'':`<div class="pager"><span>${format(table.rows.length?table.offset+1:0,0)}–${format(Math.min(table.offset+table.rows.length,table.matched),0)} / ${format(table.matched,0)}</span><div class="actions"><button class="button small" data-action="table-page" data-offset="${Math.max(0,table.offset-table.limit)}" ${table.offset===0?'disabled':''}>${t('previous')}</button><button class="button small" data-action="table-page" data-offset="${table.offset+table.limit}" ${table.has_more?'':'disabled'}>${t('next')}</button></div></div>`}`}
function curveChart(table){const keys=table.columns.map(c=>c.key),xkey=keys.includes('Min_child_reads')?'Min_child_reads':'Iteration',ykey=keys.includes('Log10_CPI')?'Log10_CPI':'log_CPI',step=keys.includes('Through_min_child_reads');const partial=table.has_more?(L.language==='it'?`Il grafico mostra soltanto le prime ${format(table.rows.length,0)} di ${format(table.total,0)} righe. Apri la tabella completa o il PDF originale per consultare tutti i risultati.`:`The chart shows only the first ${format(table.rows.length,0)} of ${format(table.total,0)} rows. Open the full table or original PDF to inspect all results.`):'';const interval=step?(L.language==='it'?'Gli estremi degli intervalli sono inclusi.':'Interval endpoints are inclusive.'):'';const pts=table.rows.filter(r=>number(r[xkey])!==null&&number(r[ykey])!==null&&(!step||(number(r.Through_min_child_reads)!==null&&Number(r.Through_min_child_reads)>=Number(r[xkey]))));if(!pts.length)return empty(t('curveEmpty'))+(partial?notice(partial,'warning'):'');let xs=pts.flatMap(r=>[Number(r[xkey]),...(step?[Number(r.Through_min_child_reads)]:[])]),ys=pts.map(r=>Number(r[ykey]));let xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);if(xmin===xmax){xmin-=.5;xmax+=.5}const pad=ymin===ymax?1:(ymax-ymin)*.12;ymin-=pad;ymax+=pad;const W=740,H=250,left=85,right=25,top=30,bottom=52,X=v=>left+(v-xmin)/(xmax-xmin)*(W-left-right),Y=v=>top+(ymax-v)/(ymax-ymin)*(H-top-bottom);const grid=[0,.25,.5,.75,1].map(f=>{const v=ymin+(ymax-ymin)*f,y=Y(v);return `<line class="chart-grid" x1="${left}" x2="${W-right}" y1="${y}" y2="${y}"/><text x="${left-10}" y="${y+4}" text-anchor="end">${format(v,2)}</text>`}).join('');const unique=[...new Set(xs)],tickValues=unique.length<10?unique:[xmin,(xmin+xmax)/2,xmax];const ticks=tickValues.map(v=>`<text x="${X(v)}" y="${H-bottom+23}" text-anchor="middle">${format(v,0)}</text>`).join('');const marks=pts.map(r=>{const x=X(Number(r[xkey])),y=Y(Number(r[ykey])),end=step?X(Number(r.Through_min_child_reads)):x;return `${step?`<path class="curve-line" d="M${x},${y} L${end},${y}"/>`:''}<circle class="curve-dot" cx="${x}" cy="${y}" r="4"><title>${esc(r[xkey])}${step?'–'+esc(r.Through_min_child_reads):''} · ${esc(r[ykey])}</title></circle>${step?`<circle class="curve-dot" cx="${end}" cy="${y}" r="4"/>`:''}`}).join('');return `<div class="chart-scroll" tabindex="0"><svg viewBox="0 0 ${W} ${H}" class="curve-chart" role="img" aria-label="log10 CPI"><title>log₁₀(CPI)</title>${grid}${ticks}${marks}<text x="17" y="17">log₁₀(CPI)</text><text x="${W/2}" y="${H-8}" text-anchor="middle">${t('threshold')}</text></svg></div><p class="help">${t('curveHelp')} ${esc(interval)}</p>${partial?notice(partial,'warning'):''}`}
function renderFiles(files=state.files,includeCopies=false){const shown=files.filter(file=>includeCopies||file.canonical!==false),copies=includeCopies?[]:files.filter(file=>file.canonical===false);return `<div class="file-list">${shown.map(f=>`<article class="file-row"><span class="file-icon">${esc(f.kind==='table'?f.name.split('.').pop().toUpperCase():f.kind.toUpperCase())}</span><div><b>${esc(f.label||f.name)}</b><small>${esc([moduleName(f.module),f.marker,f.sample_label,f.family_label,f.analysis?choiceLabel(f.analysis):''].filter(Boolean).join(' · '))} · ${format(f.size_bytes/1024,1)} KB</small><details class="file-name"><summary>${t('fileName')}</summary>${esc(f.relative_path||f.name)}</details></div><div class="actions">${['table','pdf'].includes(f.kind)?button(t('open'),'open-file',{id:f.id},'small','file'):''}${button(t('download'),'export-file',{id:f.id},'small quiet','download')}</div></article>`).join('')||(copies.length?'':empty(t('noResults')))}</div>${copies.length?`<details class="disclosure"><summary>${L.language==='it'?'Copie di presentazione con i nomi dei campioni':'Presentation copies with sample names'} · ${copies.length}</summary><div class="details-body">${renderFiles(copies,true)}</div></details>`:''}`}
function resultRowDetails(row,columns){const groups=[['',columns.filter(c=>!/_mother$|_father$|_child$/.test(c.key))],...[['mother','mother'],['father','father'],['child','child']].map(([key,label])=>[t(label),columns.filter(c=>c.key.endsWith('_'+key))])];return groups.filter(([,cols])=>cols.length).map(([name,cols])=>`${name?`<h3 class="section-gap">${name}</h3>`:''}<dl class="detail-values">${cols.map(c=>`<div><dt>${esc(c.label)}</dt><dd>${resultCell(row[c.key],c)}${number(row[c.key])!==null?`<small>${t('originalValue')}: ${esc(row[c.key])}</small>`:''}${c.description?`<small>${esc(c.description)}</small>`:''}</dd></div>`).join('')}</dl>`).join('')}
function renderModule(){const group=currentGroup();if(!group)return empty(t('noResults'));const entry=currentEntry();return `<div class="toolbar">${select(t('markers'),'result-marker',(state.overview.modules||[]).filter(g=>g.module===group.module).map(g=>[g.module+'|'+g.marker,g.marker]),state.module,'data-result="module"')}${group.entries.length?select(group.module==='contamination'||group.module.endsWith('-call')?t('sample'):t('family'),'result-entry',group.entries.map((e,i)=>[String(i),entryLabel(e)]),String(state.entry),'data-result="entry"'):''}</div>${group.warnings?.map(w=>notice(typeof w==='string'?w:w.message,'warning')).join('')||''}${entry?`${metrics(entry.metrics||[])}${genotypeBars(entry)}${entry.row?`<details class="disclosure"><summary>${t('summary')}</summary><div class="details-body">${resultRowDetails(entry.row,Object.keys(entry.row).map(key=>state.table?.columns.find(c=>c.key===key)||{key,label:resultFieldLabel(key)}))}</div></details>`:''}${state.curves.map(curve=>`<section class="section-gap"><div class="section-title"><h3>${t('curves')}${curve.file.cutoff?' · '+esc(curve.file.cutoff):''}</h3>${button(t('download'),'export-file',{id:curve.file.id},'small','download')}</div>${curveChart(curve)}<details class="disclosure"><summary>${t('details')}</summary><div class="details-body">${tableView(curve,{compact:true,all:true})}${button(t('open'),'open-file',{id:curve.file.id},'small','arrow')}</div></details></section>`).join('')}${state.table?`<div class="section-title"><h3>${t('siteDetails')}</h3>${button(t('download'),'export-file',{id:state.table.file.id},'small','download')}</div><div class="toolbar"><input id="site-search" class="input stretch" aria-label="${t('search')}" placeholder="${t('siteSearch')}" data-search="table" value="${esc(state.tableSearch)}"><label class="check-row"><input type="checkbox" data-field="allColumns" ${state.allColumns?'checked':''}><span>${t('allColumns')}</span></label></div>${tableView(state.table)}`:''}${group.matrix_file_ids?.length?`<details class="disclosure"><summary>${L.language==='it'?'Confronta i genotipi dei campioni':'Compare sample genotypes'}</summary><div class="details-body">${group.matrix_file_ids.map(id=>button(t('open'),'open-file',{id},'small','file')).join('')}</div></details>`:''}`:empty(t('noResults'))}<details class="disclosure"><summary>${t('originals')}</summary><div class="details-body">${renderFiles(group.files||[])}</div></details>${resultHelp()}`}
function resultFieldLabel(key){const fieldMap={Pair:['Coppia','Pair'],Trio:['Trio','Trio'],Marker_type:[t('markers'),t('markers')],Analysis:[t('phaseSelection'),t('phaseSelection')],CPI:['Indice di paternità combinato','Combined Paternity Index'],Log10_CPI:['log₁₀(CPI)','log₁₀(CPI)'],CPI_medianFF:['log₁₀(CPI) alla frazione fetale mediana','log₁₀(CPI) at median fetal fraction'],Median_fetal_fraction_percent:['Frazione fetale mediana (%)','Median fetal fraction (%)'],Median_fetal_fraction_raw:['Frazione fetale mediana (proporzione)','Median fetal fraction (proportion)'],N_sites_mother:['Siti informativi materni','Maternal informative sites'],N_sites_father:['Siti informativi paterni','Paternal informative sites'],Min_logCPI:['Minimo log₁₀(CPI)','Minimum log₁₀(CPI)'],Max_logCPI:['Massimo log₁₀(CPI)','Maximum log₁₀(CPI)'],Mean_logCPI:['Media log₁₀(CPI)','Mean log₁₀(CPI)'],Median_logCPI:['Mediana log₁₀(CPI)','Median log₁₀(CPI)'],Error_constant:['Probabilità di errore','Error probability'],Min_fetal_reads:[L.field('min_fetal_reads'),L.field('min_fetal_reads')],Min_child_reads:[L.field('min_child_reads'),L.field('min_child_reads')],N_sites:['Siti inclusi','Included sites'],N_heterozygous_child_sites:['Siti con figlio eterozigote','Heterozygous child sites'],N_homozygous_child:['Siti con figlio omozigote','Homozygous child sites'],Matching_sites:['Siti compatibili con il padre','Sites matching the father'],Mismatching_sites:['Siti incompatibili con il padre','Sites mismatching the father'],individuo:[t('sample'),t('sample')],informative_sites:['Siti informativi','Informative sites'],mean_contamination:['Contaminazione media (proporzione)','Mean contamination (proportion)'],sd_contamination:['Deviazione standard (proporzione)','Standard deviation (proportion)'],Cutoff:['Pannello di selezione','Selection panel']};return fieldMap[key]?.[L.language==='en'?1:0]||L.field(key)}
function renderRun(){const run=state.run,groups=state.overview?.modules||[];let content='';if(state.runTab==='results'){content=`<div class="module-tabs" role="tablist"><button role="tab" aria-selected="${!state.module}" class="${!state.module?'active':''}" data-action="result-module" data-module="">${t('summary')}</button>${[...new Set(groups.map(g=>g.module))].map(module=>`<button role="tab" aria-selected="${currentGroup()?.module===module}" class="${currentGroup()?.module===module?'active':''}" data-action="result-module" data-module="${esc(groups.find(g=>g.module===module).module+'|'+groups.find(g=>g.module===module).marker)}">${module.endsWith('-call')?module.startsWith('dnp')?'DNP':'SNP':moduleName(module)}</button>`).join('')}<button role="tab" aria-selected="${state.module==='files'}" class="${state.module==='files'?'active':''}" data-action="result-module" data-module="files">${t('files')}</button></div><div class="results-body">${state.module==='files'?`<div class="section-title"><h2>${t('files')}</h2>${button(t('downloadAll'),'export-run',{},'','download')}</div>`+renderFiles():state.module?renderModule():renderResultsSummary()}</div>`}else if(state.runTab==='samples'){content=`<div class="table-scroll"><table class="table"><thead><tr><th>${t('sampleName')}</th><th>${t('sampleFile')}</th></tr></thead><tbody>${run.samples.map(s=>`<tr><td>${esc(s.label||s.id)}</td><td>${esc(s.filename)}<details class="file-name"><summary>${t('details')}</summary>${esc(s.path||'')}</details></td></tr>`).join('')}</tbody></table></div>`}else if(state.runTab==='parameters'){content=renderArchivedSettings(run)}else{content=`<div class="panel-body"><dl class="review-list"><dt>${t('status')}</dt><dd>${badge(run.status)}</dd><dt>${t('date')}</dt><dd>${date(run.started_at)} → ${date(run.finished_at)}</dd><dt>NIPAT</dt><dd>${esc(run.version||'—')}</dd></dl>${run.error?notice(typeof run.error==='string'?run.error:run.error.message||JSON.stringify(run.error),'error'):''}${(run.warnings||[]).map(w=>notice(w.message||w.reason||JSON.stringify(w),'warning')).join('')}<details class="disclosure"><summary>${t('files')}</summary><div class="details-body">${renderFiles(state.files.filter(f=>!f.module))}</div></details></div>`}return heading(run.name||run.id,'',button(t('allExperiments'),'back-archive',{},'','back'),t('archive'))+`<div class="meta-row"><span>${date(run.started_at)}</span><span>${esc(run.markers.join(' / '))}</span><span>${run.samples.length} ${t('samples').toLowerCase()}</span>${badge(run.status)}</div>${run.status!=='succeeded'?notice(t('partialResults'),'warning'):''}<section class="panel section-gap"><div class="tabs" role="tablist">${[['results','results'],['samples','samples'],['parameters','usedSettings'],['provenance','provenance']].map(([value,key])=>`<button class="tab ${state.runTab===value?'active':''}" role="tab" aria-selected="${state.runTab===value}" data-action="run-tab" data-tab="${value}">${t(key)}</button>`).join('')}</div>${content}</section><div class="section-title"><div><h3>${t('newFromSettings')}</h3><p class="help">${t('preferencesHelp')}</p></div>${button(t('reuse'),'reuse-run',{},'','plus')}</div>`}
function archivedFlagNames(value){
 if(!Number.isSafeInteger(Number(value))||Number(value)<0)return displayValue(value);
 const flags=[[1,'Letture appaiate','Paired reads'],[2,'Coppie corrette','Proper pairs'],[4,'Non allineate','Unmapped'],[8,'Compagno non allineato','Unmapped mate'],[16,'Filamento inverso','Reverse strand'],[32,'Compagno sul filamento inverso','Mate on reverse strand'],[64,'Prima lettura della coppia','First read in pair'],[128,'Seconda lettura della coppia','Second read in pair'],[256,'Allineamenti secondari','Secondary alignments'],[512,'Controllo qualità non superato','Failed quality control'],[1024,'Duplicati','Duplicates'],[2048,'Allineamenti supplementari','Supplementary alignments']];
 const selected=flags.filter(([bit])=>(Number(value)&bit)!==0).map(([,it,en])=>L.language==='en'?en:it);
 if(Number(value)>4095)selected.push((L.language==='it'?'Altre categorie':'Additional categories')+': '+value);
 return selected.join(' · ')||t('emptyValue')
}
function renderArchivedSettings(run){
 const sections=(run.settings||[]).map(snapshot=>{
  const document=snapshot.document||{},step=(run.steps||[]).find(s=>s.id===snapshot.step_id),sample=(run.samples||[]).find(s=>s.id===step?.sample_id);
  const label=[moduleName(snapshot.module),snapshot.marker,sample?.label||sample?.id].filter(Boolean).join(' · ');
  const parameters=Object.entries(document.parameters||{}).map(([key,value])=>`<div><dt>${esc(L.field(key))}<small>${t(phase(key))}</small></dt><dd>${esc(absent(value)?t('notAvailable'):key==='excluded_flags'?archivedFlagNames(value):typeof value==='string'?choiceLabel(value):displayValue(value))}</dd></div>`).join('');
  const constants=Object.entries(document.constants||{}).map(([key,stored])=>{
   const entry=stored&&typeof stored==='object'&&!Array.isArray(stored)?stored:{value:stored},current=state.settings[snapshot.module]?.constants?.[key];
   const sameModel=current&&JSON.stringify(current.value)===JSON.stringify(entry.value);
   const description=sameModel?constantDescription(key,entry):(typeof entry.description==='object'?entry.description[L.language]||entry.description.it||entry.description.en||'':entry.description||'');
   const value=sameModel?constantValue(snapshot.module,key,entry):`<div class="readonly-value">${esc(displayValue(entry.value))}</div>`;
   return `<section class="parameter-group"><h3>${esc(L.field(key))}</h3>${description?`<p class="help">${esc(description)}</p>`:''}${value}</section>`
  }).join('');
  return `<details class="disclosure" open><summary>${esc(label)}</summary><div class="details-body"><dl class="detail-values">${parameters}</dl>${constants?`<details class="disclosure"><summary>${t('constants')} · ${t('readOnly')}</summary><div class="details-body">${constants}</div></details>`:''}</div></details>`
 }).join('');
 const executionLabels={input_hashes:'hashes',cpus:'cpuLimit',memory_mb:'memoryLimit',pids_limit:'processLimit',performance_diagnostics:'diagnostics',execution_mode:'mode',max_workers:'maxWorkers',dnp_block_mib:'blockSize',dnp_block_loci:'blockLoci'};
 const execution=Object.entries(run.execution||{}).map(([key,value])=>{
  const label=executionLabels[key]?t(executionLabels[key]):L.field(key),rendered=value===null?t('automatic'):value==='auto'?t('automatic'):value==='serial'?t('serial'):key==='input_hashes'&&value==='full'?t('fullHashes'):displayValue(value);
  return `<div><dt>${esc(label)}</dt><dd>${esc(rendered)}</dd></div>`
 }).join('');
 const provenance=L.language==='it'?'Valori registrati per questo esperimento, conservati in sola lettura.':'Recorded values for this experiment, preserved as read only.';
 return `<div class="panel-body"><p class="help">${provenance}</p>${sections}${execution?`<details class="disclosure"><summary>${t('execution')} · ${t('readOnly')}</summary><div class="details-body"><dl class="detail-values">${execution}</dl></div></details>`:''}${!sections&&!execution?empty(t('noResults')):''}</div>`
}
function math(expr,label){return `<div class="formula"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block" aria-label="${esc(label)}"><mrow>${expr}</mrow></math></div>`}
const mn=v=>`<mn>${v}</mn>`,mi=v=>`<mi>${v}</mi>`,mo=v=>`<mo>${esc(v)}</mo>`,sub=(v,s)=>`<msub>${mi(v)}<mtext>${s}</mtext></msub>`,frac=(a,b)=>`<mfrac><mrow>${a}</mrow><mrow>${b}</mrow></mfrac>`,power=(a,b)=>`<msup><mrow>${a}</mrow><mrow>${b}</mrow></msup>`,par=s=>mo('(')+s+mo(')');
function constantValue(module,key,entry){const nr=sub('n','REF'),na=sub('n','ALT'),no=sub('n',L.language==='en'?'other':'altre'),sum=nr+mo('+')+na,label=L.field(key);let expr='';
 if(key==='phred_error_probability')expr=mi('ε')+mo('=')+power(mn(10),mo('−')+frac(mi('Q'),mn(10)));
 else if(key==='count_ratio')expr=mi('r')+mo('=')+frac(nr,sum);
 else if(key==='other_fraction_denominator')expr=nr+mo('+')+na+mo('+')+no;
 else if(key==='site_contamination')expr=sub('c','i')+mo('=')+frac(sub('n',L.language==='en'?'unexpected':'inattese'),sum);
 else if(key==='sample_contamination')expr=mi('c')+mo('=')+frac(mn(1),mi('m'))+`<munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>m</mi></munderover>`+sub('c','i');
 else if(key==='pi_formula')expr=sub('PI','i')+mo('=')+frac(sub('t','i'),sub('p','i'));
 else if(key==='fetal_fraction_formula')expr=mi('F')+mo('=')+`<mi mathvariant="normal">${L.language==='en'?'median':'mediana'}</mi>`+par(frac(mn(2)+mo('·')+sub('n',L.language==='en'?'fetal':'fetali'),sum));
 else if(key==='likelihood_formula'){const g=mi('g'),eps=mi('ε'),p=par(frac(mn(2)+mo('−')+g,mn(2))+mo('·')+par(mn(1)+mo('−')+eps)+mo('+')+frac(g,mn(2))+mo('·')+eps);expr=sub('ℓ','REF')+par(g)+mo('=')+`<mo>∑</mo><mi mathvariant="normal">ln</mi>`+p;return math(expr,label)+`<p class="help">${L.language==='en'?'REF observations; REF/ALT weights are exchanged for ALT. The selected genotype maximizes the combined natural log-likelihood. Other reads do not contribute.':'Osservazioni REF; per ALT i pesi REF/ALT sono scambiati. Il genotipo scelto massimizza la somma delle log-verosimiglianze naturali. Le altre letture non contribuiscono.'}</p>`}
 else if(key==='heterozygous_transmission')expr=mi('P')+mo('=')+frac(mn(1),mn(2));
 else if(key==='homozygous_transmission')expr=mi('P')+mo('=')+mn(1);
 else if(key==='population_frequencies')expr=mn(0)+mo('<')+mi('p')+mo('≤')+mn(1);
 else if(key==='log_cpi_base')expr=`<msub><mi mathvariant="normal">log</mi>${mn(10)}</msub>`+par('<mi mathvariant="normal">CPI</mi>');
 if(expr)return math(expr,label);
 const meanings={missing_result:[t('notAvailable'),t('notAvailable')],one_site_sd:[t('notAvailable'),t('notAvailable')],likelihood_log_base:['Logaritmo naturale (base e)','Natural logarithm (base e)'],indel_policy:['Escludi le osservazioni con inserzioni o delezioni in una posizione della finestra.','Discard observations with an insertion or deletion at any position in the window.'],maternal_selection:['Siti con madre omozigote','Sites with a homozygous mother'],curve_threshold_semantics:['Supporto dell’allele paterno obbligato dopo il filtro iniziale degli alleli del figlio.','Obligatory paternal allele support after the initial child genotype support filter.'],likelihood_quality:module==='dnp-call'?['Media aritmetica delle qualità Phred delle due basi centrali','Arithmetic mean of the two central Phred qualities']:['Qualità Phred della base SNP centrale','Phred quality of the central SNP base']};return `<div class="readonly-value">${esc(meanings[key]?.[L.language==='en'?1:0]??displayValue(entry.value))}</div>`}
function constantDescription(key,entry){if(L.language!=='en')return entry.description||'';return {ploidy:'Diploid model; changing ploidy requires a different scientific model.',allele_alphabet:'Alleles supported by this model.',missing_result:'A missing estimate or genotype is not equivalent to zero.',phred_offset:'Phred+33 quality encoding, not a quality threshold.',phred_error_probability:'Definition of the conversion from Phred quality to error probability.',genotypes:'Diploid states in the biallelic model.',likelihood_log_base:'Likelihoods are sums of natural logarithms, not normalized probabilities.',other_filter_comparison:'Comparison used at the other-read threshold.',indel_policy:'Applies to the complete observation window.',window_bases:'The site plus one flanking base on each side.',count_ratio:'REF fraction among REF and ALT observations only.',likelihood_quality:'Flanking bases determine whether a complete window exists.',likelihood_formula:'The called genotype maximizes the likelihood of REF and ALT observations.',other_fraction_denominator:'All REF, ALT and other observations.',site_contamination:'Unexpected reads divided by REF and ALT reads at each informative site.',sample_contamination:'Arithmetic mean of retained per-site contamination estimates.',one_site_sd:'Sample standard deviation is undefined with a single informative site.',heterozygous_transmission:'Mendelian transmission from a heterozygous father.',homozygous_transmission:'Mendelian transmission from a homozygous father.',log_cpi_base:'Base of the logarithm reported for the Combined Paternity Index.',population_frequencies:'Allele frequencies must be finite, positive and no greater than one.',pi_formula:'Paternal transmission probability, or the mismatch error probability, divided by the population frequency of the obligatory allele.',fetal_fraction_formula:'Median of twice the fetal read fraction at informative sites.',maternal_selection:'The postnatal model selects homozygous maternal sites.',curve_threshold_semantics:'The curve threshold is evaluated after the initial support filter.'}[key]||''}
function renderCatalog(){const modules=Object.keys(state.settings).filter(m=>state.catalogModule==='all'||state.catalogModule===m);return heading(t('catalog'),state.catalogDefaults?t('preferencesHelp'):'',state.catalogDefaults?button(t('savePreferences'),'save-preferences',{},'primary','check'):'')+`<section class="panel"><div class="panel-body"><div class="toolbar"><input id="catalog-search" class="input stretch" placeholder="${t('parameterSearch')}" aria-label="${t('search')}" value="${esc(state.catalogSearch)}" data-search="catalog">${select(t('analysis'),'catalog-module',[['all',t('all')],...Object.keys(state.settings).map(m=>[m,moduleName(m)])],state.catalogModule,'data-field="catalogModule"')}${select(t('catalog'),'catalog-type',[['parameters',t('parameters')],['constants',t('constants')]],state.catalogType,'data-field="catalogType"')}</div>${modules.map(m=>{const content=state.catalogType==='parameters'?parameterRows(m,state.catalogDefaults?'defaults':'draft',!state.catalogDefaults,true):Object.entries(state.settings[m].constants).filter(([key,p])=>[L.field(key),constantDescription(key,p)].join(' ').toLowerCase().includes(state.catalogSearch.toLowerCase())).map(([key,p])=>`<div class="parameter-row"><div><h3>${esc(L.field(key))}</h3><p>${esc(constantDescription(key,p))}</p>${constantValue(m,key,p)}</div><div><span class="badge neutral">${t('readOnly')}</span></div></div>`).join('');return content?`<section class="parameter-group"><h2>${moduleName(m)}</h2>${content}</section>`:''}).join('')}</div></section>`}
function renderPreferences(){const p=state.preferences;return heading(t('settings'),t('preferencesHelp'),button(t('savePreferences'),'save-preferences',{},'primary','check'))+`<div class="grid two-columns"><section class="panel"><div class="panel-header"><h2>${t('dataDirectory')}</h2></div><div class="panel-body">${fileField(t('dataDirectory'),'preference.data_dir',p.data_dir||state.boot.layout.data_dir,'directory')}<div class="section-gap">${fileField(t('runsDirectory'),'preference.runs_dir',p.runs_dir||state.boot.layout.runs_dir,'directory')}</div><div class="divider"></div><h3>${t('scientificDefaults')}</h3><div class="actions section-gap">${button(t('editDefaults'),'edit-defaults',{},'','catalog')}</div></div></section><section class="panel"><div class="panel-header"><h2>${t('updates')}</h2></div><div class="panel-body">${select(t('updateChannel'),'update-channel',[['stable',t('stable')],['testing',t('testing')]],p.update_channel,'data-preference="update_channel"')}<label class="check-row section-gap"><input type="checkbox" data-preference="check_updates_on_startup" ${p.check_updates_on_startup?'checked':''}><span>${t('checkStartup')}</span></label><div class="divider"></div><div class="settings-row"><div><b>${t('motion')}</b><p>${t('motionHelp')}</p></div><input aria-label="${t('motion')}" type="checkbox" data-field="motion" ${state.motion?'checked':''}></div></div></section></div><section class="panel section-gap"><div class="panel-header"><h2>${t('execution')}</h2></div><div class="panel-body">${executionFields(p.execution||{},'defaults')}</div></section>`}
function renderResources(){const s=state.environment||{},runtime=s.runtime||{};const rows=[[L.language==='it'?'Computer':'Computer',s.host],[L.language==='it'?'Ambiente · configurazione salvata':'Environment · saved configuration',runtime.configured],[L.language==='it'?'Ambiente · risorse effettive':'Environment · effective resources',runtime.effective],[L.language==='it'?'Limiti delle analisi':'Analysis limits',s.container]];return `<table class="table"><thead><tr><th>${t('environment')}</th><th>CPU</th><th>RAM · MiB</th></tr></thead><tbody>${rows.map(([label,v])=>`<tr><td>${esc(label)}</td><td>${format(v?.cpus,2)}</td><td>${format(v?.memory_mib,0)}</td></tr>`).join('')}</tbody></table>${(s.warnings||[]).map(w=>notice(w,'warning')).join('')}${s.backend==='wsl'?notice(L.language==='it'?'RAM e CPU di WSL2 sono condivise con tutte le distribuzioni WSL2 dell’utente.':'WSL2 memory and CPU limits are shared by all WSL2 distributions for this user.','warning'):''}${['wsl','lima'].includes(s.backend)?`<div class="form-row">${input(t('memoryLimit'),'runtime-memory',state.runtimeMemory??runtime.configured?.memory_mib??'','type="number" min="128" data-field="runtimeMemory"')}${input(t('cpuLimit'),'runtime-cpus',state.runtimeCpus??runtime.configured?.cpus??'','type="number" min="1" data-field="runtimeCpus"')}</div>${button(t('previewResources'),'preview-resources',{},'','settings')}`:''}`}
function renderInstallation(){const s=state.installation;if(!s)return '';const items=[...(s.runtimes||[]),...(s.cache||[])];return `<details class="disclosure"><summary>${L.language==='it'?'Installazione e spazio':'Installation and storage'}</summary><div class="details-body">${items.map(item=>`<div class="settings-row"><div><b>${esc(item.name)}</b><p>${format(item.size_bytes/1024/1024,1)} MiB · ${esc(item.reason||'')}</p><p class="path">${esc(item.path)}</p></div>${item.removable?button(t('remove'),'maintain',{operation:'cleanup',target:item.id},'danger small'):''}</div>`).join('')}${s.recovery?.reason?`<p class="help section-gap">${esc(s.recovery.reason)}</p>`:''}${s.recovery?.recoverable?button(L.language==='it'?'Ripara / riprendi preparazione':'Repair / resume setup','maintain',{operation:'recover',target:s.recovery.id},'','settings'):''}${(s.warnings||[]).map(w=>notice(w,'warning')).join('')}</div></details>`}
function renderUpdate(){const u=state.update;return `<section class="panel section-gap"><div class="panel-header"><h2>${t('updates')}</h2>${button(L.language==='it'?'Controlla aggiornamenti':'Check for updates','check-updates',{},'','activity')}</div><div class="panel-body">${u?`<p>${esc(u.message||u.status)}</p>${u.offer?`<p class="section-gap"><b>NIPAT ${esc(u.offer.version)}</b> · ${esc(u.offer.channel)}</p><div class="actions section-gap">${button(L.language==='it'?'Scarica e verifica':'Download and verify','download-update',{},'primary','download')}${u.downloaded?button(L.language==='it'?'Installa e chiudi NIPAT':'Install and close NIPAT','install-update',{},'','check'):''}</div>`:''}`:`<p class="help">${t('updateChannel')}: ${t(state.preferences.update_channel)}</p>`}</div></section>`}
function renderEnvironment(){return heading(t('environment'),t('environmentHelp'),button(t('checkEnvironment'),'check-environment',{},'primary','check'))+`<section class="panel"><div class="panel-header"><h2>${t('resourceSettings')}</h2>${button(t('reload'),'load-resources',{},'small','activity')}</div><div class="panel-body">${state.environment?renderResources():empty(t('loading'))}</div></section>${state.environmentCheck?`<div class="section-gap">${notice(L.language==='it'?'Verifica dell’ambiente completata.':'Environment check completed.')}<details class="disclosure"><summary>${t('logs')}</summary><div class="details-body"><pre class="job-log">${esc(state.environmentCheck.logs.join('\n'))}</pre></div></details></div>`:''}${renderUpdate()}${renderInstallation()}<section class="panel section-gap"><div class="panel-body"><h2>${t('helpTitle')}</h2><p class="section-gap">${t('helpText')}</p></div></section>`}
function renderIGV(){const v=state.igv;return heading(t('igv'),t('igvHelp'))+`<section class="panel"><div class="panel-body"><div class="form-row">${fileField(t('reference'),'igv-reference.fasta',v.reference.fasta,'reference')}${fileField(t('fastaIndex'),'igv-reference.index',v.reference.index,'index')}</div><div class="section-title"><h3>${L.language==='it'?'Tracce':'Tracks'}</h3>${button(t('addTrack'),'igv-add-track',{},'small','plus')}</div>${v.tracks.map((track,i)=>`<div class="igv-track">${input(t('name'),'track-name-'+i,track.name,`data-track-name="${i}"`)}${fileField(t('alignment'),`igv-track.${i}.path`,track.path,'alignment')}${fileField(t('alignmentIndex'),`igv-track.${i}.index`,track.index,'index')}${button(t('remove'),'igv-remove-track',{index:i},'quiet small','close')}</div>`).join('')}<div class="actions section-gap">${button(t('loadGenome'),'igv-load',{},'primary','igv')}<span class="help">${t('igvMissing')}</span></div></div></section><div class="toolbar igv-toolbar"><input id="igv-locus" class="input stretch" value="${esc(v.locus)}" aria-label="${t('region')}" placeholder="${t('regionExample')}" data-field="igvLocus">${button(t('goRegion'),'igv-search',{},'','arrow')}${button(t('saveSession'),'igv-save',{},'','download')}</div><div id="igv-container" class="igv-container">${empty(t('igvNotLoaded'))}</div>`}
function render(){if(!state.boot)return;const existingIgv=state.view==='igv'&&state.igv.loaded?$('igv-container'):null;renderGeneration++;$('navigation').innerHTML=nav.map((key,i)=>`${i===5?'<div class="nav-divider"></div>':''}<button class="nav-button ${state.view===key?'active':''}" data-action="navigate" data-view="${key}" ${state.view===key?'aria-current="page"':''}>${icon(key)}<span>${t(key)}</span></button>`).join('');$('breadcrumb').textContent='NIPAT / '+t(state.view);$('version').textContent=state.boot.version+' · prerelease';$('language').value=L.language;document.querySelectorAll('[data-text]').forEach(el=>el.textContent=t(el.dataset.text));const active=state.jobs.filter(j=>!terminal(j));$('job-indicator').textContent=active.length?active.length+' · '+t('running'):'';$('main').innerHTML=({home:renderHome,new:renderNew,archive:renderArchive,activity:renderActivity,catalog:renderCatalog,settings:renderPreferences,environment:renderEnvironment,igv:renderIGV}[state.view]||renderHome)();if(existingIgv){$('igv-container').replaceWith(existingIgv);window.NipatIGV?.resize?.()}}
function refreshPreservingInput(id){const inputElement=$(id),start=inputElement?.selectionStart,value=inputElement?.value;render();const next=$(id);if(next){next.focus();if(typeof start==='number'&&next.setSelectionRange)next.setSelectionRange(start,start)}}
function humanError(error){let message=String(error?.message||error||t('operationError'));message=message.replace(/--(dnp|snp)-(contamination-panel|cpi-cutoffs|cpin-panel|popfreq|panel)/g,(_,marker,kind)=>({panel:t('panel'),popfreq:t('population'),'contamination-panel':t('contaminationPanel'),'cpi-cutoffs':t('cpiPanels'),'cpin-panel':t('cpinPanel')}[kind]+' '+marker.toUpperCase()));for(const key of Object.keys(L.fields).sort((a,b)=>b.length-a.length))message=message.replaceAll(key,L.field(key));for(const module of Object.keys(state.settings))message=message.replaceAll(module,moduleName(module));return message}
function showError(error){const message=humanError(error);if(state.view==='new'){state.error=message;render()}else toast(message)}
function modal(title,body,footer=''){previousFocus=document.activeElement;$('modal-root').innerHTML=`<div class="modal-backdrop" data-action="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-header"><h2 id="dialog-title">${esc(title)}</h2>${button(t('close'),'close-modal',{},'small','close')}</header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;$('modal-root').querySelector('button')?.focus()}
function closeModal(){$('modal-root').innerHTML='';previousFocus?.focus?.()}
async function loadRun(id){const version=++runLoadVersion;++entryLoadVersion;++tableLoadVersion;const [run,overview,files]=await Promise.all([rpc('runs.get',{run_id:id}),rpc('runs.overview',{run_id:id}),rpc('runs.files',{run_id:id})]);if(version!==runLoadVersion)return;state.run=run;state.runId=id;state.overview=overview;state.files=files.files||files;state.runTab='results';state.module=null;state.table=null;state.curves=[];state.entry=0;state.view='archive';render();$('main').focus()}
async function loadEntry(){const version=++entryLoadVersion;++tableLoadVersion;const context=[state.runId,state.module,state.entry].join('|');const entry=currentEntry();state.table=null;state.tableFile=null;state.curves=[];state.tableOffset=0;state.tableSearch='';if(!entry){render();return}const group=currentGroup(),file=entry.site_file_id||(group.module.endsWith('-call')?entry.file_id:null);const [table,curves]=await Promise.all([file?rpc('runs.table',{run_id:state.runId,file_id:file,offset:0,limit:100}):null,Promise.all((entry.curve_file_ids||[]).map(id=>rpc('runs.table',{run_id:state.runId,file_id:id,offset:0,limit:1000})))]);if(version!==entryLoadVersion||context!==[state.runId,state.module,state.entry].join('|'))return;state.table=table;state.tableFile=file;state.curves=curves;render()}
async function loadTable(offset=0){if(!state.tableFile)return;const version=++tableLoadVersion;const context=[state.runId,state.module,state.entry,state.tableFile].join('|');const table=await rpc('runs.table',{run_id:state.runId,file_id:state.tableFile,offset,limit:100,query:state.tableSearch});if(version!==tableLoadVersion||context!==[state.runId,state.module,state.entry,state.tableFile].join('|'))return;state.table=table;state.tableOffset=offset;render()}
function safeLocalUrl(url){const parsed=new URL(url,location.href);if(parsed.origin!==location.origin||!['http:','https:'].includes(parsed.protocol))throw new Error(t('operationError'));return parsed.href}
async function openFile(id){const file=state.files.find(f=>f.id===id);if(!file)return;if(file.kind==='table'){const table=await rpc('runs.table',{run_id:state.runId,file_id:id,offset:0,limit:100});state.modalTable=table;modal(file.label||file.name,tableView(table,{compact:true,all:true})+`<div class="pager"><span>${format(table.rows.length,0)} / ${format(table.total,0)} ${t('rows')}</span><div class="actions"><button class="button small" data-action="modal-table-page" data-offset="0" disabled>${t('previous')}</button><button class="button small" data-action="modal-table-page" data-offset="100" ${table.has_more?'':'disabled'}>${t('next')}</button></div></div>`,button(t('download'),'export-file',{id},'','download'));}else if(file.kind==='pdf'){const info=await rpc('files.url',{run_id:state.runId,file_id:id});modal(file.label||file.name,`<p class="help">${t('pdfFallback')}</p><iframe class="pdf-preview" src="${esc(safeLocalUrl(info.url))}" title="${esc(file.label||file.name)}"></iframe>`,button(t('download'),'export-file',{id},'','download'))}}
async function navigate(view){if(!nav.includes(view))return;++runLoadVersion;++entryLoadVersion;++tableLoadVersion;if(state.view==='igv'&&view!=='igv'){++igvLoadVersion;window.NipatIGV?.dispose();state.igv.loaded=false}state.error='';state.view=view;if(view==='archive')state.run=null;render();$('main').focus();try{if(['home','archive'].includes(view)){await loadRuns();if(state.view===view)render()}else if(view==='activity'){const jobs=await rpc('jobs.list');state.jobs=jobs.jobs||jobs;if(state.view===view)render()}else if(view==='environment'){const results=await Promise.allSettled([rpc('resources.get'),rpc('installation.get')]);if(results[0].status==='fulfilled')state.environment=results[0].value;else showError(results[0].reason);if(results[1].status==='fulfilled')state.installation=results[1].value;if(state.view===view)render()}}catch(error){showError(error)}}
async function savePreferences(){const saved=await rpc('preferences.save',{preferences:state.preferences,baseline:state.baseline});state.preferences=clone(saved);state.baseline=clone(saved);await rpc('ui.save',{preferences:{language:L.language,reduce_motion:!state.motion}});toast(t('saved'))}
function showConfirmation(title,message,action,data={}){modal(title,`<p>${esc(message)}</p>`,button(t('cancel'),'close-modal')+button(title,action,data,'primary'))}
function safeSampleId(path,kind){let name=basename(path).replace(/\.[^.]+$/,'').replace(/[^A-Za-z0-9_-]/g,'_');if(!/^[A-Za-z]/.test(name))name='S_'+name;name=name.slice(0,42)||'Sample';let candidate=name,n=2;while(state.draft.samples.some(s=>s.id.toLowerCase()===candidate.toLowerCase()&&(s.kind===kind||(!s.kind.endsWith('-table')&&!kind.endsWith('-table')))))candidate=name+'_'+n++;return candidate}
async function action(name,data,element){
 if(name==='navigate')return navigate(data.view);
 if(name==='archive-page'){state.archivePage=Math.max(0,Number(data.page));render();return}
 if(name==='retry-boot')return boot();
 if(name==='close-modal')return closeModal();
 if(name==='modal-backdrop'){closeModal();return}
 if(name==='choose-path'){await choosePath(data.key,data.filter);render();return}
 if(name==='clear-path'){setPath(data.key,null);render();return}
 if(name==='add-samples'){const kind=state.sampleKind,paths=await choosePath(null,kind==='bam'?'bam':kind==='snp-pileup'?'pileup':'table',true);for(const path of paths){if(state.draft.samples.some(s=>s.path===path&&s.kind===kind))continue;state.draft.samples.push({id:safeSampleId(path,kind),path,kind})}invalidate();render();return}
 if(name==='remove-sample'){state.draft.samples.splice(Number(data.index),1);invalidate();render();return}
 if(name==='step'){const next=Number(data.index);if(next>state.step&&(!state.draft.name.trim()||!state.draft.samples.length)){state.error=t('inputRequired');render();return}state.step=next;state.error='';render();return}
 if(name==='add-family'){const rows=state.draft.families[data.module];let n=rows.length+1;while(rows.some(r=>r.id==='Family_'+n))n++;rows.push({id:'Family_'+n,mother:'',father:'',...(data.module==='cpin'?{child:''}:{})});invalidate();render();return}
 if(name==='remove-family'){state.draft.families[data.module].splice(Number(data.index),1);invalidate();render();return}
 if(name==='add-cutoff'){const r=state.draft.resources[data.marker];r.cpi_cutoffs??=[];r.cpi_cutoffs.push({label:'Panel_'+(r.cpi_cutoffs.length+1),path:''});invalidate();render();return}
 if(name==='remove-cutoff'){state.draft.resources[data.marker].cpi_cutoffs.splice(Number(data.index),1);invalidate();render();return}
 if(name==='reset-param'){const target=data.scope==='defaults'?(state.preferences.scientific_settings[data.module]??={}):state.draft.scientific_settings[data.module];target[data.key]=state.settings[data.module].parameters[data.key].default;invalidate();render();return}
 if(name==='validate-plan'){state.error='';const revision=draftRevision;const result=await rpc('plan.preview',{draft:submittedDraft()});if(revision!==draftRevision){toast(L.language==='it'?'La configurazione è cambiata. Verificala di nuovo.':'Configuration changed. Validate it again.');return}state.preview=result;render();return}
 if(name==='start-analysis'){if(!state.preview)return;const job=await rpc('analysis.start',{preview_id:state.preview.preview_id});state.jobs.unshift(job);state.preview=null;state.view='activity';render();await loadRuns();return}
 if(name==='refresh-jobs'){const jobs=await rpc('jobs.list');state.jobs=jobs.jobs||jobs;render();return}
 if(name==='cancel-job'){showConfirmation(t('stopAnalysis'),t('stopConfirm'),'confirm-cancel-job',{id:data.id});return}
 if(name==='confirm-cancel-job'){await rpc('jobs.cancel',{job_id:data.id});closeModal();const jobs=await rpc('jobs.list');state.jobs=jobs.jobs||jobs;render();return}
 if(name==='open-run')return loadRun(data.id);
 if(name==='back-archive'){state.run=null;state.module=null;return navigate('archive')}
 if(name==='import-run'){const paths=await choosePath(null,'directory');if(paths.length){const result=await rpc('runs.import',{path:paths[0]});await loadRuns();const id=result.imported?.[0];if(id)return loadRun(id);state.view='archive';state.run=null;render()}return}
 if(name==='run-tab'){state.runTab=data.tab;render();return}
 if(name==='result-module'){++entryLoadVersion;++tableLoadVersion;state.module=data.module||null;state.entry=0;state.tableSearch='';if(state.module&&state.module!=='files')await loadEntry();else render();return}
 if(name==='table-page')return loadTable(Number(data.offset));
 if(name==='open-file')return openFile(data.id);
 if(name==='export-file'){await rpc('files.export',{run_id:state.runId,file_id:data.id});return}
 if(name==='export-run'){await rpc('runs.export',{run_id:state.runId});return}
 if(name==='row-details'){const table=await rpc('runs.table',{run_id:state.runId,file_id:data.file,offset:Number(data.row),limit:1});if(table.rows[0])modal(t('siteDetails'),resultRowDetails(table.rows[0],table.columns),button(t('download'),'export-file',{id:data.file},'','download'));return}
 if(name==='modal-table-page'){const table=await rpc('runs.table',{run_id:state.runId,file_id:state.modalTable.file.id,offset:Number(data.offset),limit:100});state.modalTable=table;modal(table.file.label||table.file.name,tableView(table,{compact:true,all:true})+`<div class="pager"><span>${format(table.offset+1,0)}–${format(table.offset+table.rows.length,0)} / ${format(table.total,0)}</span><div class="actions"><button class="button small" data-action="modal-table-page" data-offset="${Math.max(0,table.offset-100)}" ${!table.offset?'disabled':''}>${t('previous')}</button><button class="button small" data-action="modal-table-page" data-offset="${table.offset+100}" ${!table.has_more?'disabled':''}>${t('next')}</button></div></div>`,button(t('download'),'export-file',{id:table.file.id},'','download'));return}
 if(name==='reuse-run'){applyDraft(await rpc('run.reuse',{run_id:state.runId}));return navigate('new')}
 if(name==='prepare-module'){if(data.module.endsWith('-call')){applyDraft(await rpc('run.reuse',{run_id:state.runId}));state.draft.caller=data.module.startsWith('dnp')?'dnp':'snp';state.source='bam';state.draft.samples=state.draft.samples.filter(sample=>sample.kind==='bam'||state.draft.caller==='snp'&&sample.kind==='snp-pileup');state.draft.branches={DNP:[],SNP:[]}}else{applyDraft(await rpc('run.prepare',{run_id:state.runId,module:data.module}));state.step=1}return navigate('new')}
 if(name==='edit-defaults'){state.catalogDefaults=true;state.catalogType='parameters';state.catalogSearch='';return navigate('catalog')}
 if(name==='save-preferences')return savePreferences();
 if(name==='load-resources'){state.environment=await rpc('resources.get');render();return}
 if(name==='check-environment'){state.environmentCheck=await rpc('environment.check',{check_runtime:true});state.environment=await rpc('resources.get');render();return}
 if(name==='preview-resources'){state.resourcePreview=await rpc('resources.preview',{memory_mib:Number(state.runtimeMemory??state.environment.runtime.configured.memory_mib),cpus:Number(state.runtimeCpus??state.environment.runtime.configured.cpus)});const r=state.resourcePreview;modal(t('resourceConfirm'),`<dl class="review-list"><dt>RAM · MiB</dt><dd>${format(r.before?.memory_mib,0)} → ${format(r.after.memory_mib,0)}</dd><dt>CPU</dt><dd>${format(r.before?.cpus,0)} → ${format(r.after.cpus,0)}</dd></dl>${(r.warnings||[]).map(w=>notice(w,'warning')).join('')}${r.affected_running?.length?`${notice(t('resourceRestart'),'warning')}<p class="section-gap">${esc(r.affected_running.join(', '))}</p><label class="check-row"><input type="checkbox" id="confirm-resource-restart"><span>${L.language==='it'?'Confermo il riavvio degli ambienti indicati':'I confirm restarting the listed environments'}</span></label>`:''}`,button(t('cancel'),'close-modal')+button(t('applyResources'),'apply-resources',{},'primary'));return}
 if(name==='apply-resources'){const restart=!!$('confirm-resource-restart')?.checked;const result=await rpc('resources.apply',{preview_id:state.resourcePreview.preview_id,confirmed:true,restart_confirmed:restart});closeModal();state.environment=await rpc('resources.get');state.resourcePreview=null;render();if(result.status==='saved-restart-required')toast(t('resourceRestart'));else toast(t('saved'));return}
 if(name==='check-updates'){state.update=await rpc('updates.check',{channel:state.preferences.update_channel});render();return}
 if(name==='download-update'){const offerId=state.update.offer_id;await rpc('updates.download',{offer_id:offerId});if(state.update.offer_id===offerId)state.update.downloaded=true;render();return}
 if(name==='install-update'){showConfirmation(L.language==='it'?'Installa aggiornamento':'Install update',L.language==='it'?`Installare NIPAT ${state.update.offer.version} e chiudere l’app?`:`Install NIPAT ${state.update.offer.version} and close the app?`,'confirm-install-update');return}
 if(name==='confirm-install-update'){const r=await rpc('updates.install',{offer_id:state.update.offer_id,confirmed:true});closeModal();if(r.close_required)await rpc('app.close');return}
 if(name==='maintain'){const item=[...(state.installation.runtimes||[]),...(state.installation.cache||[])].find(i=>i.id===data.target)||state.installation.recovery;showConfirmation(data.operation==='cleanup'?t('remove'):(L.language==='it'?'Ripara installazione':'Repair installation'),`${item.name||''} ${item.path||''}\n${item.reason||''}\n${L.language==='it'?'NIPAT verrà chiuso per questa operazione.':'NIPAT will close for this operation.'}`,'confirm-maintain',{operation:data.operation,target:data.target});return}
 if(name==='confirm-maintain'){const r=await rpc('installation.maintain',{operation:data.operation,target:data.target,confirmed:true});closeModal();if(r.close_required)await rpc('app.close');return}
 if(name==='igv-add-track'){state.igv.tracks.push({name:'',path:'',index:''});render();return}
 if(name==='igv-remove-track'){state.igv.tracks.splice(Number(data.index),1);render();return}
 if(name==='igv-load'){const version=++igvLoadVersion;window.NipatIGV?.dispose();state.igv.loaded=false;render();$('igv-container').innerHTML=empty(t('viewerLoading'));const request=clone({reference:state.igv.reference,tracks:state.igv.tracks,locus:state.igv.locus});try{const prepared=await rpc('igv.prepare',request);if(state.view!=='igv'||version!==igvLoadVersion)return;window.NipatIGV.setLanguage(L.language);await window.NipatIGV.mount($('igv-container'),prepared);if(state.view!=='igv'||version!==igvLoadVersion)return;state.igv.loaded=true;state.igv.loadedSources=request}catch(error){if(state.view==='igv'&&version===igvLoadVersion){state.igv.loaded=false;$('igv-container').innerHTML=notice(humanError(error),'error')}throw error}return}
 if(name==='igv-search'){await window.NipatIGV.search(state.igv.locus);return}
 if(name==='igv-save'){const snapshot=await window.NipatIGV.exportSession(),sources=state.igv.loadedSources||state.igv;await rpc('igv.session.save',{session:{schema_version:1,reference:sources.reference,tracks:sources.tracks,locus:snapshot.locus||state.igv.locus,view:snapshot}});return}
}
function onValue(target){const value=target.type==='checkbox'?target.checked:target.value;
 if(target.dataset.draft){state.draft[target.dataset.draft]=value;invalidate();if(target.dataset.draft==='caller')render();return}
 if(target.dataset.sample!==undefined){state.draft.samples[Number(target.dataset.sample)].id=value;invalidate();return}
 if(target.dataset.family){const [m,index,key]=target.dataset.family.split('|');state.draft.families[m][Number(index)][key]=value;invalidate();return}
 if(target.dataset.branch){const [marker,module]=target.dataset.branch.split('|'),branch=state.draft.branches[marker];if(value&&!branch.includes(module))branch.push(module);if(!value)state.draft.branches[marker]=branch.filter(m=>m!==module);invalidate();render();return}
 if(target.dataset.cutoff){const [m,index]=target.dataset.cutoff.split('|');state.draft.resources[m].cpi_cutoffs[Number(index)].label=value;invalidate();return}
 if(target.dataset.parameter){const [module,key,scope]=target.dataset.parameter.split('|');const def=state.settings[module].parameters[key];const v=def.type==='boolean'?!!value:def.type==='string'?value:value===''?null:Number(value);const dest=scope==='defaults'?(state.preferences.scientific_settings[module]??={}):state.draft.scientific_settings[module];dest[key]=v;invalidate();return}
 if(target.dataset.flag){const [module,bit,scope]=target.dataset.flag.split('|');const dest=scope==='defaults'?(state.preferences.scientific_settings[module]??={}):state.draft.scientific_settings[module];const current=dest.excluded_flags??state.settings[module].parameters.excluded_flags.default;dest.excluded_flags=value?current|Number(bit):current&~Number(bit);invalidate();render();return}
 if(target.dataset.execution){const [key,scope]=target.dataset.execution.split('|');const dest=scope==='defaults'?state.preferences.execution:state.draft.execution;dest[key]=['execution_mode','input_hashes'].includes(key)?value:key==='performance_diagnostics'?!!value:value===''?null:Number(value);invalidate();return}
 if(target.dataset.preference){state.preferences[target.dataset.preference]=value;return}
 if(target.dataset.trackName!==undefined){state.igv.tracks[Number(target.dataset.trackName)].name=value;return}
 if(target.dataset.field){const key=target.dataset.field;if(key==='source'){state.source=value;state.draft.caller=value==='tables'?'tables':state.draft.caller==='tables'?'dnp':state.draft.caller;state.sampleKind=value==='tables'?'dnp-table':'bam';if(value==='tables'){state.draft.samples=state.draft.samples.filter(s=>s.kind.endsWith('-table'));state.draft.reference=null}else if(value==='bam')state.draft.samples=state.draft.samples.filter(s=>!s.kind.endsWith('-table'));invalidate();render()}else if(key==='igvLocus'){state.igv.locus=value}else if(key==='runtimeMemory'||key==='runtimeCpus'){state[key]=value;state.resourcePreview=null}else{state[key]=value;if(key==='archiveStatus'||key==='archiveMarker')state.archivePage=0;if(key==='sampleKind'&&value==='snp-pileup'&&state.draft.caller==='dnp'){state.draft.caller='snp';invalidate()}if(key!=='motion')render();else rpc('ui.save',{preferences:{language:L.language,reduce_motion:!value}}).catch(showError)}return}
 if(target.dataset.result){if(target.dataset.result==='module'){state.module=value;state.entry=0}else state.entry=Number(value);loadEntry().catch(showError);return}
}
async function changeLanguage(language){L.setLanguage(language);window.NipatIGV?.setLanguage(language);await rpc('ui.save',{preferences:{language:L.language,reduce_motion:!state.motion}});if(state.run){const saved={id:state.runId,module:state.module,entry:state.entry,tab:state.runTab};await loadRun(saved.id);state.module=saved.module;state.entry=saved.entry;state.runTab=saved.tab;if(state.module&&state.module!=='files')await loadEntry();else render()}else render()}
function bind(){document.addEventListener('click',async event=>{const element=event.target.closest('[data-action]');if(!element||element.disabled)return;if(element.dataset.action==='modal-backdrop'){if(event.target===element)closeModal();return}event.preventDefault();const actionName=element.dataset.action;const longAction=['validate-plan','start-analysis','import-run','reuse-run','prepare-module','check-environment','check-updates','download-update','igv-load'].includes(actionName);try{element.disabled=true;if(longAction){$('operation-indicator').textContent=t('loading');element.setAttribute?.('aria-busy','true');}await action(actionName,element.dataset,element)}catch(error){showError(error)}finally{element.disabled=false;if(longAction){$('operation-indicator').textContent='';element.removeAttribute?.('aria-busy');}}});
 document.addEventListener('change',event=>{if(event.target.id==='language'){changeLanguage(event.target.value).catch(showError);return}onValue(event.target)});
 document.addEventListener('input',event=>{const el=event.target;if(el.dataset.search){clearTimeout(searchTimer);const kind=el.dataset.search;const value=el.value;if(kind==='archive'){state.archiveSearch=value;state.archivePage=0;refreshPreservingInput('archive-search')}else if(kind==='catalog'){state.catalogSearch=value;refreshPreservingInput('catalog-search')}else{state.tableSearch=value;searchTimer=setTimeout(()=>loadTable(0).then(()=>$('site-search')?.focus()).catch(showError),300)}return}if(el.tagName==='INPUT'&&!['checkbox','radio'].includes(el.type))onValue(el)});
 document.addEventListener('keydown',event=>{const dialog=$('modal-root').querySelector('[role=dialog]');if(dialog){if(event.key==='Escape'){closeModal();return}if(event.key==='Tab'){const nodes=[...dialog.querySelectorAll('button,input,select,summary,[tabindex="0"]')].filter(n=>!n.disabled);const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}}else if(event.key==='Enter'&&event.target.id==='igv-locus'){event.preventDefault();action('igv-search',{}).catch(showError)}});
}
async function poll(){try{const jobs=await rpc('jobs.list');const before=state.jobs.map(j=>j.status).join('|');state.jobs=jobs.jobs||jobs;const active=state.jobs.filter(j=>!terminal(j));$('job-indicator').textContent=active.length?active.length+' · '+t('running'):'';if(state.view==='activity'&&!$('modal-root').innerHTML){const logOpen=[...document.querySelectorAll('.disclosure')].map(d=>d.open);render();document.querySelectorAll('.disclosure').forEach((d,i)=>d.open=logOpen[i]||false)}if(before!==state.jobs.map(j=>j.status).join('|')){await loadRuns();if(state.view==='home')render()}}catch{/* A transient poll error must not replace work in progress. */}finally{pollTimer=setTimeout(poll,state.jobs.some(j=>!terminal(j))?1500:5000)}}
async function boot(){delete document.documentElement.dataset.nipatReady;try{const data=await rpc('bootstrap');state.boot=data;state.settings=data.settings?.workflows||data.settings||{};state.preferences=clone(data.preferences);state.preferences.scientific_settings??={};state.preferences.execution??={};state.baseline=clone(data.preferences);state.jobs=data.jobs||[];state.motion=!data.ui?.reduce_motion;L.setLanguage(data.ui?.language||'it');state.draft=blankDraft();await loadRuns();render();document.documentElement.dataset.nipatReady='true';clearTimeout(pollTimer);pollTimer=setTimeout(poll,1500);if(state.preferences.check_updates_on_startup){rpc('updates.check',{channel:state.preferences.update_channel}).then(result=>{state.update=result;if(result.offer)toast(result.message)}).catch(()=>{})}}catch(error){$('main').innerHTML=heading(t('loadingFailed'))+notice(humanError(error),'error')+`<div class="actions section-gap">${button(t('retry'),'retry-boot',{},'primary')}</div>`}}
window.NipatApp={state,rpc,boot,render,navigate,action,onValue,activeMarkers,selectedModules,blankDraft,normalizeDraft,submittedDraft,loadRuns,parameterVisible,range,choiceLabel,metricValue,resultCell,shownColumns,curveChart,constantValue,genotypeBars,jobProgress,terminal,safeSampleId,missing:absent,number,esc,changeLanguage,loadRun,loadEntry,loadTable,renderRun,renderNew};
bind();boot();
})();
